// Auto-generated mouth sprite assets for Stickman Lip-Sync & Expressions.
// Images are real transparent PNG mouth sprites, loaded via static public paths or embedded data URIs.

export type StickmanMouthShape =
  | "rest"
  | "A"
  | "I"
  | "U"
  | "E"
  | "O"
  | "smile"
  | "frown"
  | "smirk"
  | "surprised";

/** Static public URL paths served from /public/stickman/mouth/ */
export const STICKMAN_MOUTH_URLS: Record<StickmanMouthShape, string> = {
  "rest": "/stickman/mouth/rest.png",
  "A": "/stickman/mouth/A.png",
  "I": "/stickman/mouth/I.png",
  "U": "/stickman/mouth/U.png",
  "E": "/stickman/mouth/E.png",
  "O": "/stickman/mouth/O.png",
  "smile": "/stickman/mouth/smile.png",
  "frown": "/stickman/mouth/frown.png",
  "smirk": "/stickman/mouth/smirk.png",
  "surprised": "/stickman/mouth/surprised.png",
};

/** Embedded Data URIs (base64 PNG) guaranteeing instant zero-flicker frame sync in Remotion and SVG */
export const STICKMAN_MOUTH_DATA_URIS: Record<StickmanMouthShape, string> = {
  "rest": "data:image/png;base64,",
  "A": "data:image/png;base64,",
  "I": "data:image/png;base64,",
  "U": "data:image/png;base64,",
  "E": "data:image/png;base64,",
  "O": "data:image/png;base64,",
  "smile": "data:image/png;base64,",
  "frown": "data:image/png;base64,",
  "smirk": "data:image/png;base64,",
  "surprised": "data:image/png;base64,",
};

/** getStickmanMouthImage returns the embedded data URI (or public path) for any mouth shape. */
export function getStickmanMouthImage(shape: string): string {
  const key = (shape in STICKMAN_MOUTH_DATA_URIS ? shape : "rest") as StickmanMouthShape;
  return STICKMAN_MOUTH_DATA_URIS[key];
}
